    static void addI2JPackage(String string) {
        int n = string.indexOf(58);
        if (n < 0) {
            System.out.println("Incorrect format for i2jpackage mapping: " + string);
            System.exit(1);
        }
        String string2 = string.substring(0, n);
        String string3 = string.substring(n + 1);
        if (string2.length() == 0) {
            package_prefix = string3;
            if (logger.isDebugEnabled()) {
                logger.debug("Replace unnamed global package with " + string3);
            }
        } else {
            pack_replace.put(string2, string3);
            if (logger.isDebugEnabled()) {
                logger.debug("Replace pack " + string2 + " with " + string3);
            }
        }
    }

